/** JSON-RPC error object. */
export type Error = {
  /** A number indicating the error type that occurred. This MUST be an integer as defined in the JSON-RPC specification. */
  code: ErrorCode;
  /** A string providing a short description of the error. The message SHOULD be limited to a concise single sentence. */
  message: string;
  /** Optional primitive or structured value that contains additional information about the error. This may include debugging information or context-specific details. */
  data?: ErrorData | null;
};

/** Predefined error codes for common JSON-RPC and ACP-specific errors. */
export type ErrorCode = -32700 | -32600 | -32601 | -32602 | -32603 | -32800 | -32000 | -32002 | -32022 | number;

/** Schema for the `data` field of an error: the shapes ACP defines, or any other value. */
export type ErrorData = UnsupportedProtocolVersionErrorData | SessionNotFoundErrorData | unknown;

/** Data for the `-32022` (Unsupported protocol version) error. */
export type UnsupportedProtocolVersionErrorData = {
  /** The protocol version the Client requested. */
  requested: ProtocolVersion;
  /** The protocol versions the Agent supports. */
  supported: Array<ProtocolVersion>;
  /** The _meta property is reserved by ACP to allow Clients and Agents to attach additional metadata to their interactions. Omitted and `null` are equivalent and mean no metadata. Implementations MUST NOT assign meaning to keys they do not recognize. */
  _meta?: { [key: string]: unknown } | null;
};

/** Data for the `-32002` (Resource not found) error when a session-scoped request names a session that does not exist or is not active. */
export type SessionNotFoundErrorData = {
  /** The session ID from the request. */
  sessionId: SessionId;
  /** The _meta property is reserved by ACP to allow Clients and Agents to attach additional metadata to their interactions. Omitted and `null` are equivalent and mean no metadata. Implementations MUST NOT assign meaning to keys they do not recognize. */
  _meta?: { [key: string]: unknown } | null;
};

/** Details of a failure that ended active work. */
export type ErrorStopReason = {
  /** The failure, as a JSON-RPC error object. */
  error?: Error | null;
};

/** This capability is not part of the spec yet, and may be removed or changed at any point. */
export type Usage = {
  /** Sum of all token types for the completed work. */
  totalTokens: number;
  /** Input tokens for the completed work. */
  inputTokens: number;
  /** Output tokens for the completed work. */
  outputTokens: number;
  /** Thought/reasoning tokens for the completed work. */
  thoughtTokens?: number | null;
  /** Cache read tokens for the completed work. */
  cachedReadTokens?: number | null;
  /** Cache write tokens for the completed work. */
  cachedWriteTokens?: number | null;
  /** The _meta property is reserved by ACP to allow Clients and Agents to attach additional metadata to their interactions. Omitted and `null` are equivalent and mean no metadata. Implementations MUST NOT assign meaning to keys they do not recognize. */
  _meta?: { [key: string]: unknown } | null;
};

/** No foreground work is active. Background activity may continue. */
export type IdleStateUpdate = {
  /** This capability is not part of the spec yet, and may be removed or changed at any point. */
  usage?: Usage | null;
  /** Work running independently of foreground work, as a complete snapshot. */
  background?: Array<BackgroundWork> | null;
  /** The _meta property is reserved by ACP to allow Clients and Agents to attach additional metadata to their interactions. Omitted and `null` are equivalent and mean no metadata. Implementations MUST NOT assign meaning to keys they do not recognize. */
  _meta?: { [key: string]: unknown } | null;
  /** Why foreground work stopped. The value selects one of this type's variants, which may add fields of their own. */
  stopReason?: string | null;
} & ({
  stopReason: "end_turn";
} | {
  stopReason: "max_tokens";
} | {
  stopReason: "max_turn_requests";
} | {
  stopReason: "refusal";
} | {
  stopReason: "cancelled";
} | ({
  stopReason: "error";
} & ErrorStopReason) | {
  /** Custom or future stop reason. */
  stopReason: string;
  [key: string]: unknown;
} | {
  stopReason?: null;
});

